26	static inline u32 svm_flag_to_mms_type(u64 flag)
27	{
28	    if (svm_flag_attr_is_hpage(flag) || svm_flag_attr_is_gpage(flag)) {
29	        if (svm_flag_attr_is_p2p(flag)) {
30	            return MMS_TYPE_P2P_HPAGE;
31	        } else {
32	            return MMS_TYPE_HPAGE;
33	        }
34	    } else {
35	        if (svm_flag_attr_is_p2p(flag)) {
36	            return MMS_TYPE_P2P_NPAGE;
37	        } else {
38	            return MMS_TYPE_NPAGE;
39	        }
40	    }
41	}
