43	static u64 svm_get_prop_aligned_size(u64 start)
44	{
45	    struct svm_prop prop;
46	    int ret;
47	
48	    ret = svm_get_prop(start, &prop);
49	    if (ret != 0) {
50	        return 0;
51	    }
52	
53	    return prop.aligned_size;
54	}
