56	int svm_module_mem_malloc(u32 devid, u32 numa_id, u64 flag, u64 *start, u64 size, u32 module_id)
57	{
58	    struct svm_malloc_location location;
59	    u64 tmp_flag = flag & (~SVM_FLAG_ATTR_VA_ONLY);
60	    u64 align;
61	    int ret;
62	
63	    ret = svm_query_page_size_by_svm_flag(devid, tmp_flag, &align);
64	    if (ret != DRV_ERROR_NONE) {
65	        svm_err("Query page size failed. (ret=%d; devid=%u; flag=0x%llx)\n", ret, devid, tmp_flag);
66	        return ret;
67	    }
68	
69	    svm_malloc_location_pack(devid, numa_id, &location);
70	    svm_flag_set_module_id(&tmp_flag, module_id);
71	
72	    ret = svm_malloc(start, size, align, tmp_flag, &location);
73	    if (ret == 0) {
74	        svm_mms_add(devid, module_id, svm_flag_to_mms_type(flag), svm_get_prop_aligned_size(*start));
75	    } else {
76	        svm_mem_stats_show(devid);
77	    }
78	
79	    return ret;
80	}
81	
82	int svm_module_mem_free(u32 devid, u64 flag, u64 start, u64 size, u32 module_id)
83	{
84	    u64 aligned_size = svm_get_prop_aligned_size(start);
85	    int ret = svm_free(start);
86	    SVM_UNUSED(size);
87	    SVM_UNUSED(module_id);
88	
89	    if (ret == DRV_ERROR_BUSY) {
90	        /* return to the user success, free again rely on an event. */
91	        ret = 0;
92	    } else if (ret == DRV_ERROR_CLIENT_BUSY) {
93	        return DRV_ERROR_BUSY;
94	    }
95	    if (ret == 0) {
96	        svm_mms_sub(devid, module_id, svm_flag_to_mms_type(flag), aligned_size);
97	    }
98	    return ret;
99	}
