101	static int svm_parse_alloc_devid(u64 flag, u32 *devid)
102	{
103	    u32 virt_mem_type = (flag >> MEM_VIRT_BIT) & ((1UL << MEM_VIRT_WIDTH) - 1);
104	
105	    *devid = flag & MEM_DEVID_MASK;
106	
107	    if ((virt_mem_type == MEM_SVM_VAL) || (virt_mem_type == MEM_HOST_AGENT_VAL) || (virt_mem_type == MEM_RESERVE_VAL)) {
108	        return DRV_ERROR_NOT_SUPPORT;
109	    } else if ((virt_mem_type == MEM_DEV_VAL) || (virt_mem_type == MEM_DVPP_VAL)) { /* dvpp now is same with device */
110	        if (*devid >= SVM_MAX_DEV_AGENT_NUM) {
111	            svm_err("Invalid devid. (devid=%u; flag=%llx)\n", *devid, flag);
112	            return DRV_ERROR_INVALID_DEVICE;
113	        }
114	        return 0;
115	    } else if ((virt_mem_type == MEM_HOST_VAL) || (virt_mem_type == MEM_HOST_UVA_VAL)) {
116	        *devid = svm_get_host_devid();
117	        return 0;
118	    } else {
119	        return DRV_ERROR_NOT_SUPPORT;
120	    }
121	}
122	
123	static int svm_parse_alloc_module_id(u64 flag, u32 *module_id)
124	{
125	    u32 tmp_module_id = svm_flag_get_module_id(flag);
126	
127	    /* RUNTIME will fill invalid model_id in some scenarios */
128	    *module_id = (tmp_module_id >= MAX_MODULE_ID) ? UNKNOWN_MODULE_ID : tmp_module_id;
129	    return 0;
130	}
131	
132	static int svm_parse_alloc_svm_flag(u64 flag, u64 *svm_flag)
133	{
134	    u32 virt_mem_type = (flag >> MEM_VIRT_BIT) & ((1UL << MEM_VIRT_WIDTH) - 1);
135	    *svm_flag = 0;
136	
137	    if ((flag & MEM_ADVISE_4G) || (flag & MEM_ADVISE_TS)) {
138	        return DRV_ERROR_NOT_SUPPORT;
139	    }
140	
141	    if (flag & MEM_READONLY) {
142	        return DRV_ERROR_NOT_SUPPORT;
143	    }
144	
145	    if (((virt_mem_type == MEM_HOST_VAL) || (virt_mem_type == MEM_HOST_UVA_VAL)) &&
146	        ((flag & MEM_PAGE_HUGE) || (flag & MEM_PAGE_GIANT))) {
147	        return DRV_ERROR_NOT_SUPPORT;
148	    }
149	
150	    if ((virt_mem_type == MEM_HOST_UVA_VAL) && ((flag & MEM_CONTIGUOUS_PHY) || (flag & MEM_ADVISE_P2P) ||
151	                                                (flag & MEM_ADVISE_BAR) || (flag & MEM_DEV_CP_ONLY))) {
152	        return DRV_ERROR_NOT_SUPPORT;
153	    }
154	
155	    if (((flag & MEM_PAGE_HUGE) || (flag & MEM_PAGE_GIANT)) && (flag & MEM_CONTIGUOUS_PHY)) {
156	        svm_run_info("Continuous can not alloc huge/giant page. (flag=0x%llx)\n", flag);
157	        return DRV_ERROR_NOT_SUPPORT;
158	    }
159	
160	    if ((flag & MEM_PAGE_HUGE) && (flag & MEM_PAGE_GIANT)) {
161	        svm_err("Alloc both giant page and huge page is invalid. (flag=0x%llx)\n", flag);
162	        return DRV_ERROR_INVALID_VALUE;
163	    }
164	
165	    if (flag & MEM_DEV_CP_ONLY) {
166	        if (!(flag & MEM_DEV)) {
167	            svm_err("Dev cp only should be dev mem. (flag=0x%llx)\n", flag);
168	            return DRV_ERROR_INVALID_VALUE;
169	        }
170	
171	        if ((flag & MEM_PAGE_HUGE) || (flag & MEM_PAGE_GIANT)) {
172	            svm_run_info("Dev cp only not support huge/giant page. (flag=0x%llx)\n", flag);
173	            return DRV_ERROR_NOT_SUPPORT;
174	        }
175	    }
176	
177	    if (flag & MEM_HOST_RW_DEV_RO) {
178	        if (!(flag & MEM_DEV) || (flag & MEM_PAGE_GIANT) || (flag & MEM_DEV_CP_ONLY)) {
179	            svm_run_info("Not support MEM_HOST_RW_DEV_RO. (flag=0x%llx)\n", flag);
180	            return DRV_ERROR_NOT_SUPPORT;
181	        }
182	    }
183	
184	    if (flag & MEM_PAGE_HUGE) {
185	        *svm_flag |= SVM_FLAG_ATTR_PA_HPAGE;
186	    }
187	
188	    if (flag & MEM_PAGE_GIANT) {
189	        *svm_flag |= SVM_FLAG_ATTR_PA_GPAGE;
190	    }
191	
192	    if (flag & MEM_CONTIGUOUS_PHY) {
193	        *svm_flag |= SVM_FLAG_ATTR_PA_CONTIGUOUS;
194	    }
195	
196	    if ((flag & MEM_ADVISE_P2P) || (flag & MEM_ADVISE_BAR)) {
197	        *svm_flag |= SVM_FLAG_ATTR_PA_P2P;
198	    }
199	
200	    if (flag & MEM_DEV_CP_ONLY) {
201	        *svm_flag |= SVM_FLAG_DEV_CP_ONLY;
202	    }
203	
204	    if (virt_mem_type == MEM_HOST_UVA_VAL) {
205	        *svm_flag |= SVM_FLAG_ATTR_MASTER_UVA;
206	    }
207	
208	    return 0;
209	}
210	
211	int svm_mem_malloc(void **va, u64 size, u64 flag)
212	{
213	    u32 devid, module_id;
214	    u64 start, svm_flag;
215	    int ret;
216	
217	    ret = svm_parse_alloc_devid(flag, &devid);
218	    if (ret != 0) {
219	        return ret;
220	    }
221	
222	    ret = svm_parse_alloc_module_id(flag, &module_id);
223	    if (ret != 0) {
224	        return ret;
225	    }
226	
227	    ret = svm_parse_alloc_svm_flag(flag, &svm_flag);
228	    if (ret != 0) {
229	        return ret;
230	    }
231	
232	    svm_flag |= SVM_FLAG_CAP_NORMAL_FREE;
233	
234	    if ((svm_flag & SVM_FLAG_DEV_CP_ONLY) == 0) {
235	        svm_flag |= SVM_FLAG_CAP_REGISTER | SVM_FLAG_CAP_UNREGISTER | SVM_FLAG_CAP_REGISTER_ACCESS;
236	        if (devid < SVM_MAX_DEV_AGENT_NUM) { /* host mem not support prefetch, ipc */
237	            svm_flag |= SVM_FLAG_CAP_IPC_CREATE | SVM_FLAG_CAP_IPC_DESTROY;
238	            svm_flag |= SVM_FLAG_CAP_PREFETCH;
239	        } else {
240	            svm_flag |= SVM_FLAG_CAP_LDST;
241	        }
242	        svm_flag |= SVM_FLAG_CAP_SYNC_COPY | SVM_FLAG_CAP_SYNC_COPY_BATCH;
243	        svm_flag |= SVM_FLAG_CAP_DMA_DESC_CONVERT | SVM_FLAG_CAP_DMA_DESC_DESTROY | SVM_FLAG_CAP_DMA_DESC_SUBMIT |
244	                    SVM_FLAG_CAP_DMA_DESC_WAIT;
245	        svm_flag |= SVM_FLAG_CAP_ASYNC_COPY_SUBMIT | SVM_FLAG_CAP_ASYNC_COPY_WAIT;
246	        svm_flag |= SVM_FLAG_CAP_SYNC_COPY_2D | SVM_FLAG_CAP_DMA_DESC_CONVERT_2D;
247	        svm_flag |= SVM_FLAG_CAP_SYNC_COPY_EX;
248	        svm_flag |= SVM_FLAG_CAP_MEMSET;
249	        svm_flag |= SVM_FLAG_CAP_GET_ATTR | SVM_FLAG_CAP_GET_ADDR_CHECK_INFO | SVM_FLAG_CAP_GET_MEM_TOKEN_INFO;
250	        svm_flag |= SVM_FLAG_CAP_GET_D2D_TRANS_WAY;
251	        if (flag & MEM_HOST_RW_DEV_RO) {
252	            svm_flag |= SVM_FLAG_ATTR_PG_RDONLY;
253	            svm_flag |= SVM_FLAG_CAP_MADVISE;
254	        }
255	    } else {
256	        svm_flag |= SVM_FLAG_BY_PASS_CACHE;
257	        svm_flag |= SVM_FLAG_ATTR_VA_WITHOUT_MASTER;
258	    }
259	
260	    start = 0;
261	    ret = svm_module_mem_malloc(devid, SVM_MALLOC_NUMA_NO_NODE, svm_flag, &start, size, module_id);
262	    if (ret == 0) {
263	        (*va) = (void *)(uintptr_t)start;
264	    }
265	
266	    return ret;
267	}
268	
269	int svm_mem_free(void *va)
270	{
271	    struct svm_prop prop;
272	    u64 start = (u64)(uintptr_t)va;
273	    int ret;
274	
275	    ret = svm_get_prop(start, &prop);
276	    if (ret != 0) {
277	        /* The log cannot be modified, because in the failure mode library. */
278	        svm_err("Addr is not alloced or free repeatedly. (start=0x%llx)\n", start);
279	        svm_report_addr_not_allocated("halMemFree", "pp", start);
280	        return ret;
281	    }
282	
283	    if (!svm_flag_cap_is_support_normal_free(prop.flag)) {
284	        svm_err("Addr cap is not support normal free. (va=0x%llx)\n", start);
285	        return DRV_ERROR_INVALID_VALUE;
286	    }
287	
288	    return svm_module_mem_free(prop.devid, prop.flag, start, prop.size, svm_flag_get_module_id(prop.flag));
289	}
290	
291	drvError_t halMemAllocInner(void **pp, unsigned long long size, unsigned long long flag);
292	drvError_t halMemAllocInner(void **pp, unsigned long long size, unsigned long long flag)
293	{
294	    u32 devid = 0;
295	    u32 module_id = UNKNOWN_MODULE_ID;
296	    int ret;
297	
298	    if ((pp == NULL) || (size == 0)) {
299	        svm_err("Para is invalid. (ptr_is_null=0x%llx; size=%llu)\n", (pp == NULL), size);
300	        return DRV_ERROR_INVALID_VALUE;
301	    }
302	
303	    svm_debug("Alloc enter. (ptr=0x%llx; size=%llu; flag=0x%llx)\n", (u64)(uintptr_t)*pp, size, flag);
304	
305	    ret = svm_master_init();
306	    if (ret != DRV_ERROR_NONE) {
307	        svm_err("Svm master init failed. (ret=%d)\n", ret);
308	        return ret;
309	    }
310	
311	    svm_use_pipeline();
312	    ret = svm_mem_malloc(pp, size, flag);
313	    svm_unuse_pipeline();
314	    if ((ret == DRV_ERROR_OUT_OF_MEMORY) && (svm_parse_alloc_devid(flag, &devid) == 0)) {
315	        (void)svm_parse_alloc_module_id(flag, &module_id);
316	        svm_report_oom(size, halGetMemModuleName(module_id), devid);
317	    }
318	    if (ret == DRV_ERROR_NOT_SUPPORT) {
319	        svm_run_info("Not support. (ptr=0x%llx; size=%llu; flag=0x%llx)\n", (u64)(uintptr_t)*pp, size, flag);
320	    }
321	
322	    svm_debug("Alloc exit. (ret=%d; ptr=0x%llx; size=%llu; flag=0x%llx)\n", ret, (u64)(uintptr_t)*pp, size, flag);
323	
324	    return (drvError_t)ret;
325	}
326	
327	drvError_t halMemAlloc(void **pp, unsigned long long size, unsigned long long flag)
328	{
329	    return halMemAllocInner(pp, size, flag);
330	}
331	
332	drvError_t halMemFreeInner(void *pp);
333	drvError_t halMemFreeInner(void *pp)
334	{
335	    int ret;
336	
337	    svm_debug("Free enter. (ptr=0x%llx)\n", (u64)(uintptr_t)pp);
338	
339	    if (pp == NULL) {
340	        svm_err("pp is null.\n");
341	        return DRV_ERROR_INVALID_VALUE;
342	    }
343	
344	    svm_use_pipeline();
345	    ret = svm_mem_free(pp);
346	    svm_unuse_pipeline();
347	
348	    svm_debug("Free exit. (ret=%d; ptr=0x%llx)\n", ret, (u64)(uintptr_t)pp);
349	
350	    return (drvError_t)ret;
351	}
352	
353	drvError_t halMemFree(void *pp)
354	{
355	    return halMemFreeInner(pp);
356	}
357	
358	static int svm_smp_del_mem_event_proc(u64 va)
359	{
360	    int ret;
361	
362	    ret = svm_cache_recycle_seg_release(va);
363	    if (ret == DRV_ERROR_NOT_EXIST) {
364	        ret = svm_free(va);
365	        return (ret == DRV_ERROR_CLIENT_BUSY) ? DRV_ERROR_BUSY : ret;
366	    }
367	
368	    return ret;
369	}
370	
371	static drvError_t svm_smp_del_mem_event_proc_func(unsigned int devid, const void *msg, int msg_len,
372	                                                  struct drv_event_proc_rsp *rsp)
373	{
374	    int ret, retry_cnt;
375	    const struct svm_smp_del_msg *del_msg = (const struct svm_smp_del_msg *)msg;
376	    SVM_UNUSED(msg_len);
377	
378	    retry_cnt = 0;
379	    do {
380	        svm_use_pipeline();
381	        ret = svm_smp_del_mem_event_proc(del_msg->va);
382	        svm_unuse_pipeline();
383	        if (ret != DRV_ERROR_NOT_EXIST) {
384	            /*
385	             * There may be the following scenarios:
386	             * 1. Svm_free is being executed, va_handle is erased, smp_del returns busy, and va_handle has not yet been
387	             * re-inserted;
388	             * 2. Kern sends smp del mem event, and before the user receives the event, close_device is executed, and
389	             * the handle is released.
390	             */
391	            break;
392	        }
393	        usleep(10); /* wait 10 us */
394	    } while (retry_cnt++ < 10); /* max retry 10 times */
395	
396	    if (ret != 0) {
397	        svm_warn("Free unsuccessful. (ret=%d; devid=%u; va=%llx; size=%llx; retry=%d)\n", ret, devid, del_msg->va,
398	                 del_msg->size, retry_cnt);
399	    }
400	
401	    rsp->need_rsp = false;
402	
403	    return 0;
404	}
405	
406	static struct drv_event_proc svm_smp_del_mem_event_proc_handle = {
407	    svm_smp_del_mem_event_proc_func, sizeof(struct svm_smp_del_msg), "svm_smp_del_mem_event"};
408	
409	static int __attribute__((constructor)) svm_alloc_init(void)
410	{
411	    drv_registert_event_proc(SVM_SMP_DEL_MEM_EVENT, &svm_smp_del_mem_event_proc_handle);
412	    return 0;
413	}
