350	    normal_flag |= svm_flag_attr_is_hpage(flag) ? SVM_NORMAL_MALLOC_FLAG_PA_HPAGE : 0;
351	    normal_flag |= svm_flag_attr_is_gpage(flag) ? SVM_NORMAL_MALLOC_FLAG_PA_GPAGE : 0;
352	    normal_flag |= svm_flag_attr_is_p2p(flag) ? SVM_NORMAL_MALLOC_FLAG_PA_P2P : 0;
353	    normal_flag |= svm_flag_is_dev_cp_only(flag) ? SVM_NORMAL_MALLOC_FLAG_DEV_CP_ONLY : 0;
354	    normal_flag |= svm_flag_attr_is_specified_va(flag) ? SVM_NORMAL_MALLOC_FLAG_SPACIFIED_VA : 0;
355	    normal_flag |= svm_flag_attr_is_va_without_master(flag) ? 0 : SVM_NORMAL_MALLOC_FLAG_VA_WITH_MASTER;
356	    normal_flag |= svm_flag_attr_is_master_uva(flag) ? SVM_NORMAL_MALLOC_FLAG_MASTER_UVA : 0;
357	    normal_flag |= svm_flag_attr_is_pg_rdonly(flag) ? SVM_NORMAL_MALLOC_FLAG_PG_RDONLY : 0;
358	    normal_flag |= (svm_flag_cap_is_support_sync_copy(flag) | svm_flag_cap_is_support_async_copy_submit(flag) |
359	                    svm_flag_cap_is_support_dma_desc_convert(flag) | svm_flag_cap_is_support_sync_copy_ex(flag) |
360	                    svm_flag_cap_is_support_sync_copy_2d(flag)) ?
361	                       SVM_NORMAL_MALLOC_FLAG_CAP_COPY :
362	                       0;
363	    normal_flag |= svm_flag_is_va_only_without_populate(flag) ? SVM_NORMAL_MALLOC_FLAG_VA_WITHOUT_POPULATE : 0;
