365	    if (numa_id != SVM_MALLOC_NUMA_NO_NODE) {
366	        normal_flag |= SVM_NORMAL_MALLOC_FLAG_FIXED_NUMA;
367	        normal_malloc_flag_set_numa_id(&normal_flag, numa_id);
