static int svm_mmap_char_dev_close(int fd)
{
    struct davinci_intf_close_arg arg;
    int tmp_errno;
    int ret;

    arg.device_id = 0;
    ret = strcpy_s(arg.module_name, DAVINIC_MODULE_NAME_MAX, SVM_MMAP_CHAR_DEV_NAME);
